BEGIN;
DO $test$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();p uuid:=gen_random_uuid();s uuid:=gen_random_uuid();d date;h jsonb;r jsonb;b uuid;n int;denied boolean;actor uuid;
begin
 d:=(now() at time zone 'Africa/Cairo')::date+7;d:=d+((7-extract(dow from d)::int)%7);
 insert into auth.users(id,email,raw_user_meta_data) values(u,u||'@example.test','{}'),(v,v||'@example.test','{}');
 insert into public.products(id,type,slug,title,price,currency,is_published) values(p,'session','request-'||p,'جلسة معزولة',1200,'EGP',true);
 insert into public.services(id,product_id,slug,title,duration_minutes,price,is_active,request_enabled,booking_payment_mode,minimum_notice_minutes,booking_window_days,buffer_before_minutes,buffer_after_minutes)
 values(s,p,'request-'||s,'جلسة معزولة',60,1200,true,true,'payment_required',0,30,0,0);
 insert into public.availability_rules(service_id,weekday,start_time,end_time) values(s,0,'10:00','20:00');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal1')::text,true);
 h:=public.create_booking_hold(s,d,'12:00');
 select count(*) into n from public.orders;
 r:=public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','');b:=(r->>'bookingId')::uuid;
 if r->>'bookingStatus'<>'pending' or (r->>'total')::numeric<>1200 or (r->>'confirmed')::boolean or not (r->>'requested')::boolean or (select count(*) from public.orders)<>n then raise exception 'request_result_or_financial_record_invalid';end if;
 if not exists(select 1 from public.bookings where id=b and requested_price=1200 and requested_currency='EGP' and order_id is null and request_expires_at>now()) then raise exception 'snapshot_missing';end if;
 update public.services set price=1800 where id=s;
 if public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','')->>'bookingId'<>b::text then raise exception 'retry_created_duplicate';end if;
 denied:=false;begin perform public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم آخر','01000000000','');exception when unique_violation then denied:=sqlerrm='BOOKING_ATTEMPT_CONFLICT';end;
 if not denied then raise exception 'retry_mutation_not_denied';end if;
 h:=public.create_booking_hold(s,d,'14:00');
 denied:=false;begin perform public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','');exception when check_violation then denied:=sqlerrm='PENDING_REQUEST_EXISTS';end;
 if not denied then raise exception 'multiple_pending_requests_allowed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 denied:=false;begin perform public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','');exception when invalid_parameter_value then denied:=sqlerrm='HOLD_EXPIRED';end;
 if not denied then raise exception 'other_user_not_denied';end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 update public.bookings set request_expires_at=now()-interval '1 second' where id=b;
 n:=public.expire_booking_requests();
 if n<>1 then raise exception 'first_expiry_count_%',n;end if;
 n:=public.expire_booking_requests();
 if n<>0 or not exists(select 1 from public.bookings where id=b and status='cancelled') then raise exception 'expiry_not_idempotent_%',n;end if;
 if not public.booking_slot_is_available(s,d,'12:00') then raise exception 'expiry_did_not_release_slot';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 h:=public.create_booking_hold(s,d,'12:00');
 update public.services set request_enabled=false where id=s;
 denied:=false;begin perform public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','');exception when invalid_parameter_value then denied:=sqlerrm='INVALID_PAYMENT_MODE';end;
 if not denied then raise exception 'disabled_request_mode_allowed';end if;
 update public.services set request_enabled=true where id=s;
 r:=public.complete_booking_hold_v2((h->>'holdId')::uuid,'request','اسم اختبار','01000000000','');b:=(r->>'bookingId')::uuid;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select user_id into actor from public.admin_roles where role='owner' limit 1;
 perform public.admin_update_booking_governed(actor,b,(select starts_at from public.bookings where id=b),'confirmed','https://example.test/isolated-room','اختبار معزول داخل معاملة تتراجع');
 update public.bookings set request_expires_at=now()-interval '1 second' where id=b;
 n:=public.expire_booking_requests();
 if n<>0 or (select status from public.bookings where id=b)<>'confirmed' then raise exception 'reviewed_request_expired';end if;
 perform public.cancel_customer_booking_governed(u,b,'اختبار إلغاء معزول');
 if (select status from public.bookings where id=b)<>'cancelled' or not public.booking_slot_is_available(s,d,'12:00') then raise exception 'governed_cancel_did_not_release';end if;
 if has_function_privilege('anon','public.complete_booking_hold_v2(uuid,text,text,text,text,uuid)','execute') or has_function_privilege('authenticated','public.expire_booking_requests()','execute') then raise exception 'request_permissions_invalid';end if;
 raise notice 'PASS request price snapshot, pending/no-payment, retry/conflict, ownership, single pending request, disabled mode, expiry/release, governed confirmation/cancel and service-only job';
end $test$;
ROLLBACK;
